using System.Data;using Essco.Application.HumanResources;using Microsoft.Data.SqlClient;namespace Essco.Infrastructure.Data;
public sealed class SqlServerEmployeeCompensationRepository(string cs,int timeout):IEmployeeCompensationRepository
{public async ValueTask<IReadOnlyCollection<SalaryIncrease>>IncreasesAsync(string id,CancellationToken t){await using var c=await Open(t);await using var q=Cmd("SELECT [Fecha],[PorcentajeAumento],[SalarioAnterior],[SalarioPosterior],[MontoAumento],[MotivoAumento],[UsuarioCrea] FROM [dbo].[Empleado_Aumentos] WHERE [Cedula_Empleado]=@Id ORDER BY [Fecha] DESC",c);P(q,"@Id",id);var a=new List<SalaryIncrease>();await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t))a.Add(new(DateOnly.FromDateTime(r.GetDateTime(0)),D(r,1),D(r,2),D(r,3),D(r,4),S(r,5),S(r,6)));return a;}
public async ValueTask<IReadOnlyCollection<EmployeeAdditional>>AdditionalsAsync(string id,CancellationToken t){await using var c=await Open(t);await using var q=Cmd("SELECT [Tipo],[Monto],[FechaCrea],[Estado] FROM [dbo].[Empleado_Adicionales] WHERE [Cedula_Empleado]=@Id ORDER BY [FechaCrea] DESC",c);P(q,"@Id",id);var a=new List<EmployeeAdditional>();await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t))a.Add(new(S(r,0),D(r,1),DateOnly.FromDateTime(r.GetDateTime(2)),Convert.ToInt32(r.GetValue(3))==1));return a;}
public async ValueTask<bool>AddIncreaseAsync(SalaryIncreaseInput x,CancellationToken t){await using var c=await Open(t);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable,t);decimal before;await using(var get=Cmd("SELECT [Salario] FROM [dbo].[Empleado] WITH(UPDLOCK,HOLDLOCK) WHERE [Cedula]=@Id AND ISNULL([Estado],0)=1",c,tx)){P(get,"@Id",x.EmployeeId);var value=await get.ExecuteScalarAsync(t);if(value is null or DBNull)return false;before=Convert.ToDecimal(value);}var amount=Math.Round(before*x.Percentage/100m,2);var after=before+amount;await using(var insert=Cmd("INSERT INTO [dbo].[Empleado_Aumentos]([Cedula_Empleado],[SalarioAnterior],[SalarioPosterior],[Fecha],[PorcentajeAumento],[MontoAumento],[MotivoAumento],[UsuarioCrea]) VALUES(@Id,@Before,@After,@Date,@Percentage,@Amount,@Reason,@User); UPDATE [dbo].[Empleado] SET [Salario]=@After WHERE [Cedula]=@Id",c,tx)){P(insert,"@Id",x.EmployeeId);P(insert,"@Reason",x.Reason,1000);P(insert,"@User",x.CreatedBy,200);Dec(insert,"@Before",before);Dec(insert,"@After",after);Dec(insert,"@Percentage",x.Percentage);Dec(insert,"@Amount",amount);insert.Parameters.Add("@Date",SqlDbType.Date).Value=x.Date.ToDateTime(TimeOnly.MinValue);if(await insert.ExecuteNonQueryAsync(t)!=2)return false;}await tx.CommitAsync(t);return true;}
public async ValueTask<bool>AddAdditionalAsync(string id,string type,decimal amount,CancellationToken t){await using var c=await Open(t);await using var q=Cmd("INSERT INTO [dbo].[Empleado_Adicionales]([Tipo],[Monto],[Cedula_Empleado],[FechaCrea],[Estado]) VALUES(@Type,@Amount,@Id,CAST(SYSDATETIME() AS date),0)",c);P(q,"@Id",id);P(q,"@Type",type);Dec(q,"@Amount",amount);return await q.ExecuteNonQueryAsync(t)==1;}public async ValueTask<bool>AnnulAdditionalsAsync(string id,CancellationToken t){await using var c=await Open(t);await using var q=Cmd("UPDATE [dbo].[Empleado_Adicionales] SET [Estado]=1 WHERE [Cedula_Empleado]=@Id AND ISNULL([Estado],0)=0",c);P(q,"@Id",id);return await q.ExecuteNonQueryAsync(t)>0;}
private async ValueTask<SqlConnection>Open(CancellationToken t){var c=new SqlConnection(cs);await c.OpenAsync(t);return c;}private SqlCommand Cmd(string s,SqlConnection c,SqlTransaction?tx=null)=>new(s,c,tx){CommandTimeout=timeout};private static void P(SqlCommand c,string n,string v,int z=100)=>c.Parameters.Add(n,SqlDbType.NVarChar,z).Value=v.Trim();private static void Dec(SqlCommand c,string n,decimal v){var p=c.Parameters.Add(n,SqlDbType.Decimal);p.Precision=19;p.Scale=4;p.Value=v;}private static decimal D(SqlDataReader r,int i)=>r.IsDBNull(i)?0:Convert.ToDecimal(r.GetValue(i));private static string S(SqlDataReader r,int i)=>r.IsDBNull(i)?"":Convert.ToString(r.GetValue(i))??"";}
